"use client";

import { useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { GlideHighlight, glideBox, type GlideBox } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./button-group.css";

export function ButtonGroup({
  ref,
  className,
  children,
  ...props
}: ComponentProps<"div">) {
  const group = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => group.current!, []);
  const [box, setBox] = useState<GlideBox | null>(null);

  function place(target: EventTarget | null) {
    const button =
      target instanceof Element
        ? target.closest<HTMLElement>("[data-slot=button]")
        : null;
    if (!button || !group.current?.contains(button)) return;
    setBox(glideBox(button));
  }

  function rest(next: EventTarget | null) {
    const button =
      next instanceof Element
        ? next.closest<HTMLElement>("[data-slot=button]")
        : null;
    if (button && group.current?.contains(button)) return;
    setBox((current) => (current ? { ...current, active: false } : null));
  }

  return (
    <div
      {...props}
      ref={group}
      role="group"
      data-slot="button-group"
      onPointerMove={(event) => place(event.target)}
      onPointerLeave={() => rest(null)}
      onFocus={(event) => place(event.target)}
      onBlur={(event) => rest(event.relatedTarget)}
      className={cn(
        "relative inline-flex max-w-full items-stretch gap-0.5 rounded-touch bg-raised p-[3px] shadow-raised [&>[data-slot=button]]:h-[calc(var(--control-height)-6px)] [&>[data-slot=button]]:rounded-[calc(var(--radius-touch)-3px)] [&>[data-slot=button][data-size=icon]]:w-[calc(var(--control-height)-6px)]",
        className,
      )}
    >
      <GlideHighlight box={box} />
      {children}
    </div>
  );
}

"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* button-group.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button-group"] > [data-slot="glide-highlight"] {
    top: 0;
    border-radius: 8px;
    transition:
      transform var(--duration-normal) var(--ease-out),
      width var(--duration-normal) var(--ease-out),
      height var(--duration-normal) var(--ease-out),
      opacity var(--duration-fast) var(--ease-out);
  }
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}
